import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 근태 담당자·시스템 관리자는 전체 범위를 조회하고, 임직원은 본인 데이터만 조회한다.
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

type Db = { query: (sql: string, params?: Record<string, unknown>) => Promise<any[]> };

function isManager(user: ReturnType<typeof currentUser>): boolean {
  try {
    user.require('근태 담당자', '시스템 관리자');
    return true;
  } catch {
    return false;
  }
}

function optionalId(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return text;
}

function requiredText(value: unknown, pattern: RegExp, label: string): string {
  const text = value === undefined || value === null ? '' : String(value);
  if (!pattern.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return text;
}

function pagingOf(query: Record<string, unknown>): { page: number; size: number } {
  const pageText = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
  const sizeText = query['size'] === undefined || query['size'] === '' ? String(DEFAULT_SIZE) : String(query['size']);
  if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
  }
  const size = Number(sizeText);
  if (size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '크기가 올바르지 않습니다.');
  }
  return { page: Number(pageText), size: Math.min(size, MAX_SIZE) };
}

async function resolveScope(
  db: Db,
  user: ReturnType<typeof currentUser>,
  employeeId: string | null,
  departmentId: string | null,
): Promise<{ employeeId: string | null; departmentId: string | null }> {
  if (isManager(user)) {
    return { employeeId, departmentId };
  }
  if (employeeId !== null && employeeId !== user.id) {
    throw new ApiError(403, 'QUERY_OUT_OF_SCOPE', '조회 권한 범위를 벗어났습니다.');
  }
  if (departmentId !== null) {
    const rows = await db.query(
      'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
      { userId: user.id },
    );
    const own = rows.length > 0 && rows[0].departmentId !== null ? String(rows[0].departmentId) : null;
    if (own !== departmentId) {
      throw new ApiError(403, 'QUERY_OUT_OF_SCOPE', '조회 권한 범위를 벗어났습니다.');
    }
  }
  return { employeeId: user.id, departmentId };
}

@Controller('api/v1')
export class FnSfr01802Controller {
  @Get('/attendance-dailies')
  async listAttendanceDailies(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const startDate = requiredText(query['startDate'], /^\d{4}-\d{2}-\d{2}$/, '조회 시작일');
    const endDate = requiredText(query['endDate'], /^\d{4}-\d{2}-\d{2}$/, '조회 종료일');
    const departmentIdIn = optionalId(query['departmentId'], '부서');
    const employeeIdIn = optionalId(query['employeeId'], '임직원');
    const paging = pagingOf(query);
    return transaction(async (db) => {
      const scope = await resolveScope(db, user, employeeIdIn, departmentIdIn);
      const where =
        ' FROM attendance_daily d JOIN employee e ON e.employee_id = d.employee_id' +
        ' WHERE d.work_date >= CAST(:startDate AS date) AND d.work_date <= CAST(:endDate AS date)' +
        ' AND (CAST(:employeeId AS bigint) IS NULL OR d.employee_id = CAST(:employeeId AS bigint))' +
        ' AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))';
      const base = {
        startDate,
        endDate,
        employeeId: scope.employeeId,
        departmentId: scope.departmentId,
      };
      const counted = await db.query('SELECT CAST(COUNT(*) AS integer) AS "total"' + where, base);
      const items = await db.query(
        'SELECT d.attendance_daily_id AS "attendanceDailyId", d.employee_id AS "employeeId",' +
          ' d.work_date AS "workDate", d.clock_in_at AS "clockInAt", d.clock_out_at AS "clockOutAt",' +
          ' d.source_type AS "sourceType", d.closing_status AS "closingStatus"' +
          where +
          ' ORDER BY d.work_date, d.employee_id LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...base, limit: paging.size, offset: paging.page * paging.size },
      );
      return { items, page: paging.page, size: paging.size, total: Number(counted[0].total) };
    });
  }

  @Get('/attendance-dailies/summary')
  async getAttendanceSummary(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const yearMonth = requiredText(query['yearMonth'], /^\d{4}-(0[1-9]|1[0-2])$/, '조회 연월');
    const departmentIdIn = optionalId(query['departmentId'], '부서');
    const employeeIdIn = optionalId(query['employeeId'], '임직원');
    const paging = pagingOf(query);
    return transaction(async (db) => {
      const scope = await resolveScope(db, user, employeeIdIn, departmentIdIn);
      // 가정: 근태 신청이 연결된 일별 기록만 근태 유형별로 집계한다.
      const from =
        ' FROM attendance_daily d' +
        ' JOIN attendance_request r ON r.attendance_request_id = d.attendance_request_id' +
        ' JOIN employee e ON e.employee_id = d.employee_id' +
        " WHERE d.work_date >= CAST(CAST(:yearMonth AS text) || '-01' AS date)" +
        " AND d.work_date < CAST(CAST(:yearMonth AS text) || '-01' AS date) + interval '1 month'" +
        ' AND (CAST(:employeeId AS bigint) IS NULL OR d.employee_id = CAST(:employeeId AS bigint))' +
        ' AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))';
      const base = {
        yearMonth,
        employeeId: scope.employeeId,
        departmentId: scope.departmentId,
      };
      const counted = await db.query(
        'SELECT CAST(COUNT(*) AS integer) AS "total" FROM (SELECT d.employee_id, r.attendance_type_id' +
          from +
          ' GROUP BY d.employee_id, r.attendance_type_id) t',
        base,
      );
      const items = await db.query(
        'SELECT d.employee_id AS "employeeId", r.attendance_type_id AS "attendanceTypeId",' +
          ' CAST(COUNT(*) AS integer) AS "count"' +
          from +
          ' GROUP BY d.employee_id, r.attendance_type_id' +
          ' ORDER BY d.employee_id, r.attendance_type_id' +
          ' LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...base, limit: paging.size, offset: paging.page * paging.size },
      );
      return { items, page: paging.page, size: paging.size, total: Number(counted[0].total) };
    });
  }
}

