import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Pager,
  Pairs,
  RefName,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

function pad(n: number): string {
  return n < 10 ? '0' + n : String(n);
}

function defaultMonth() {
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth() + 1;
  const last = new Date(y, m, 0).getDate();
  return {
    yearMonth: y + '-' + pad(m),
    startDate: y + '-' + pad(m) + '-01',
    endDate: y + '-' + pad(m) + '-' + pad(last),
  };
}

interface Applied {
  startDate: string;
  endDate: string;
  yearMonth: string;
  departmentId: number | string;
  employeeId: number | string;
}

export default function FnSfr01802Page({ role, notify }: PageProps) {
  const init = defaultMonth();
  const [startDate, setStartDate] = useState(init.startDate);
  const [endDate, setEndDate] = useState(init.endDate);
  const [yearMonth, setYearMonth] = useState(init.yearMonth);
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Applied>({ ...init, departmentId: '', employeeId: '' });
  const [page, setPage] = useState(0);
  const [summaryPage, setSummaryPage] = useState(0);
  const [formError, setFormError] = useState('');
  const [detail, setDetail] = useState<Row | null>(null);

  const daily = useData<Page>(
    () =>
      call<Page>('GET', '/attendance-dailies', role, undefined, {
        startDate: applied.startDate,
        endDate: applied.endDate,
        departmentId: applied.departmentId,
        employeeId: applied.employeeId,
        page,
        size: SIZE,
      }),
    [applied, page, role],
  );

  const summary = useData<Page>(
    () =>
      call<Page>('GET', '/attendance-dailies/summary', role, undefined, {
        yearMonth: applied.yearMonth,
        departmentId: applied.departmentId,
        employeeId: applied.employeeId,
        page: summaryPage,
        size: SIZE,
      }),
    [applied, summaryPage, role],
  );

  function search() {
    if (!startDate || !endDate) {
      setFormError('조회 시작일과 조회 종료일을 입력하세요.');
      return;
    }
    if (startDate > endDate) {
      setFormError('조회 시작일은 종료일보다 늦을 수 없습니다.');
      return;
    }
    if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(yearMonth)) {
      setFormError('조회 연월은 YYYY-MM 형식으로 입력하세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setSummaryPage(0);
    setApplied({ startDate, endDate, yearMonth, departmentId, employeeId });
    notify('조회했습니다.');
  }

  function reset() {
    const d = defaultMonth();
    setStartDate(d.startDate);
    setEndDate(d.endDate);
    setYearMonth(d.yearMonth);
    setDepartmentId('');
    setEmployeeId('');
    setFormError('');
  }

  const dailyRows = daily.data ? daily.data.items : [];
  const summaryRows = summary.data ? summary.data.items : [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 조건</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="조회 연월" required hint="월별 집계 기준">
            <TextInput value={yearMonth} onChange={setYearMonth} placeholder="YYYY-MM" />
          </Field>
          <Field label="조회 대상 부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
      </section>

      <section className="box span-8">
        <h2>일별 근태</h2>
        <Band total={daily.data ? daily.data.total : 0} />
        {daily.error ? <ErrorText text={daily.error} /> : null}
        <DataTable
          rows={dailyRows}
          empty="조회 결과가 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'workDate', label: '근무일자', render: (r) => <DateText value={r.workDate} /> },
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'clockInAt', label: '출근시각', render: (r) => <DateText value={r.clockInAt} time /> },
            { key: 'clockOutAt', label: '퇴근시각', render: (r) => <DateText value={r.clockOutAt} time /> },
            { key: 'sourceType', label: '기록 출처' },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r.closingStatus} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={daily.data ? daily.data.total : 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>근태 유형별 집계</h2>
        <Band total={summary.data ? summary.data.total : 0} />
        {summary.error ? <ErrorText text={summary.error} /> : null}
        <DataTable
          rows={summaryRows}
          empty="조회 결과가 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'attendanceTypeId', label: '근태 유형', render: (r) => <RefName table="attendance_type" role={role} value={r.attendanceTypeId} /> },
            { key: 'count', label: '집계 건수', render: (r) => <span>{String(r.count)}</span> },
          ]}
        />
        <Pager page={summaryPage} size={SIZE} total={summary.data ? summary.data.total : 0} onPage={setSummaryPage} />
      </section>

      {detail ? (
        <Drawer title="일별 근태 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['임직원', <RefName table="employee" role={role} value={detail.employeeId} />],
              ['근무일자', <DateText value={detail.workDate} />],
              ['출근시각', <DateText value={detail.clockInAt} time />],
              ['퇴근시각', <DateText value={detail.clockOutAt} time />],
              ['기록 출처', String(detail.sourceType)],
              ['마감 상태', <Badge value={detail.closingStatus} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
